package com.kakaplywoods.crm;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.*;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.core.userdetails.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.security.web.SecurityFilterChain;import org.springframework.web.cors.*;import java.util.*;
@Configuration public class ApiConfig {@Bean SecurityFilterChain security(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).authorizeHttpRequests(a->a.requestMatchers("/api/public/**","/actuator/health","/actuator/health/**").permitAll().anyRequest().authenticated()).httpBasic(Customizer.withDefaults()).build();}@Bean UserDetailsService users(@Value("${app.admin.username}")String username,@Value("${app.admin.password}")String password){return new InMemoryUserDetailsManager(User.withUsername(username).password("{noop}"+password).roles("ADMIN").build());}@Bean CorsConfigurationSource cors(@Value("${app.cors-origin}")String origin){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(List.of(origin));c.setAllowedMethods(List.of("GET","POST","PATCH","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type","X-Requested-With"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;}}
